  "files": [
    {
      "path": "scripts/release-bump.sh",
      "decisions": [
        {
          "id": "ADR-0580",
          "title": "Post-release workspace versioning",
          "status": "Proposed",
          "rule": "An advance never rotates CHANGELOG.md; the changelog rotates only at a release cut",
          "reason": "After each release the workspace advances to the next unreleased version, so main never carries a released version. The advance performs the version-surface sweep without the changelog rotation, because an advance is not a release cut and rotating then would mint a release section for a version that never shipped. The released version therefore exists only on the tagged commit and on the registries.",
          "decision_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/docs/adr/0580-post-release-workspace-versioning.md#L26-L45",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/release-bump.sh#L224-L238",
          "commit": "d79d8b15",
          "commit_url": "https://github.com/relatedb/relate/commit/d79d8b150561f56b4940876a067d6b7e4781d2bc",
          "checks": [
            {
              "name": "advance: empty-[Unreleased] CHANGELOG.md byte-identical — no heading inserted, [Unreleased] ref unchanged",
              "kind": "runtime",
              "number_at_pin": 2,
              "url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/tests/test_release_advance.sh#L45-L46",
              "evidence": "an advance rewrote CHANGELOG.md, minting a release section for a version that never shipped",
              "observed": "ok",
              "tap_number": 2
            },
            {
              "name": "advance: the version surfaces still advanced",
              "kind": "runtime",
              "number_at_pin": 3,
              "url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/tests/test_release_advance.sh#L48-L49",
              "evidence": "the advance did not sweep the version surfaces",
              "observed": "ok",
              "tap_number": 3
            }
          ]
        }
      ],
      "also_cites": [
        {
          "id": "ADR-0278",
          "title": "npm distribution",
          "status": "Accepted",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/release-bump.sh#L18"
        },
        {
          "id": "ADR-0560",
          "title": "crates.io and PyPI distribution",
          "status": "Proposed",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/release-bump.sh#L184"
        },
        {
          "id": "ADR-0616",
          "title": "npm platform packages resolve as file: links in the repository, registry pins injected at pack time",
          "status": "Proposed",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/release-bump.sh#L193"
        }
      ]
    }
  ],
  "note": "\"observed\" is the check's result in Patch Precedent's replay of this exact patch (matched by its changed lines, ignoring whitespace and context) against the unmodified upstream harness; \"not observed\" means no replay of this patch was found, or that replay produced no result for this check."
}

